return $input.all().map((item) => {
  const mail = item.json;
  const prompt = [
    'Classify this personal Gmail message into exactly one label.',
    'Allowed labels: invoice, receipt, transaction, shipping, shopping, travel, support, education, job, social, subscription, newsletter, system-alert, account-security, personal.',
    'Use transaction for payment activity that is not a purchase receipt or invoice: PayPal money sent/received, refunds, payouts, transfers, card/payment-method notices, automatic/preapproved payments.',
    'Use receipt only for completed purchase/order confirmations and proof-of-purchase messages.',
    'Use shipping for delivery/tracking/parcel carrier updates. Use shopping for ecommerce browsing, seller, cart, order-management, or marketplace messages that are not receipts.',
    'Use travel for flights, hotels, ride-hailing, trains, bookings, and itinerary messages.',
    'Use support for tickets, cases, RMA, warranty, and customer-service conversations.',
    'Use education for courses, classroom, assignments, certificates, exams, training, and learning platforms.',
    'Use job for recruiting, job applications, interviews, freelance proposals, contracts, and job alerts.',
    'Use social for social-network notifications, comments, likes, follows, and community messages.',
    'Use subscription for recurring plans, memberships, renewals, trials, and recurring billing notices.',
    'Return only compact JSON with keys: messageId, label, confidence, reason.',
    'Use confidence 0 to 1. Do not include markdown.',
    '',
    `messageId: ${mail.id}`,
    `from: ${mail.from || ''}`,
    `subject: ${mail.subject || ''}`,
    `snippet: ${mail.snippet || ''}`,
    `text: ${String(mail.text || '').slice(0, 4000)}`,
  ].join('\n');
  return {
    json: {
      messageId: mail.id,
      request: {
        model: 'openai/gpt-oss-120b:free',
        temperature: 0,
        max_tokens: 256,
        messages: [
          { role: 'system', content: 'You are an email classifier. Return only valid JSON.' },
          { role: 'user', content: prompt },
        ],
      },
    },
  };
});

const labelIds = {
  "invoice": "Label_5",
  "receipt": "Label_6",
  "transaction": "Label_17",
  "shipping": "Label_18",
  "shopping": "Label_19",
  "travel": "Label_20",
  "support": "Label_21",
  "education": "Label_22",
  "job": "Label_23",
  "social": "Label_24",
  "subscription": "Label_25",
  "newsletter": "Label_7",
  "system-alert": "Label_8",
  "account-security": "Label_9",
  "personal": "Label_10",
  "error": "Label_13"
};

function parseText(item) {
  return String(item.json.choices?.[0]?.message?.content || '');
}

return $input.all().map((item) => {
  let parsed = null;
  try {
    const raw = parseText(item).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
    parsed = JSON.parse(raw);
  } catch (error) {
    parsed = { messageId: '', label: 'error', confidence: 0, reason: 'OpenRouter parse failed' };
  }

  const label = Object.prototype.hasOwnProperty.call(labelIds, parsed.label) ? parsed.label : 'error';
  const confidence = Number(parsed.confidence || 0);
  const accepted = label !== 'error' && confidence >= 0.55 && parsed.messageId;
  return {
    json: {
      messageId: parsed.messageId,
      llmLabel: label,
      llmConfidence: confidence,
      llmReason: parsed.reason || '',
      labelsToAdd: [accepted ? labelIds[label] : labelIds.error],
      labelsToRemove: accepted ? ['Label_11'] : [],
    },
  };
});
